import{_ as t,a as r,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Get Product Review","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-product-review","title":"Get Single Product Review","description":"Retrieve detailed information for a specific product review.","request":"GET /api/shop/reviews/1\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 40,\\n  \\"name\\": \\"John Doe\\",\\n  \\"title\\": \\"Great air fryer\\",\\n  \\"rating\\": 4,\\n  \\"comment\\": \\"Cooks evenly and cleans easily.\\",\\n  \\"status\\": \\"pending\\",\\n  \\"createdAt\\": \\"2026-08-07T16:04:39+05:30\\",\\n  \\"updatedAt\\": \\"2026-08-07T16:04:51+05:30\\"\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"No review carries that ID","solution":"Use an ID returned by Get Product Reviews"},{"error":"401 Unauthorized","cause":"The storefront key header was missing or wrong","solution":"Send X-STOREFRONT-KEY on the request"}]}]},"headers":[],"relativePath":"api/rest-api/shop/product-reviews/get-product-review.md","filePath":"api/rest-api/shop/product-reviews/get-product-review.md","lastUpdated":1786429091000}'),o={name:"api/rest-api/shop/product-reviews/get-product-review.md"};function i(s,e,n,c,p,h){return a(),r("div",null,e[0]||(e[0]=[d('<h1 id="get-product-review" tabindex="-1">Get Product Review <a class="header-anchor" href="#get-product-review" aria-label="Permalink to &quot;Get Product Review&quot;">​</a></h1><p>Retrieve detailed information for a specific product review.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/reviews/{reviewId}</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>reviewId</code></td><td>integer</td><td>Yes</td><td>The review to read. No product ID is part of the path.</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Review ID.</td></tr><tr><td><code>name</code></td><td>string</td><td>Display name the reviewer submitted.</td></tr><tr><td><code>title</code></td><td>string</td><td>Review headline.</td></tr><tr><td><code>comment</code></td><td>string</td><td>Review body.</td></tr><tr><td><code>rating</code></td><td>integer</td><td>Star rating, 1 to 5.</td></tr><tr><td><code>status</code></td><td>string</td><td><code>pending</code> or <code>approved</code>.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><p>The product and customer behind a review are not part of this payload — there is no <code>productId</code>, no <code>customerId</code>, and no reviewer email. Helpfulness voting does not exist in the storefront API, so there are no vote counts either.</p><p>This endpoint is public and is <strong>not filtered by status</strong>: a <code>pending</code> review is readable by ID even though it is absent from the default product listing.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Read back a just-submitted review</strong> — the create response returns the ID, and this fetches the stored row without having to filter the product listing by status.</li><li><strong>Deep link to one review</strong> — a &quot;permalink&quot; route can render from this single call.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Do not use it to build a review list</strong> — the payload names neither the product nor the author, so listing per product is <a href="/api/rest-api/shop/product-reviews/get-product-reviews.html">Get Product Reviews</a>.</li><li><strong>Check <code>status</code> before displaying publicly</strong> — the endpoint hands back pending rows too, so a page that renders whatever it fetches can leak unapproved content.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/product-reviews/get-product-reviews.html">Get Product Reviews</a> — a product&#39;s reviews, approved only by default</li><li><a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a> — submit a review; it starts as pending</li><li><a href="/api/rest-api/shop/product-reviews/update-product-review.html">Update Product Review</a> — edit the customer&#39;s own review</li></ul>',18)]))}const v=t(o,[["render",i]]);export{u as __pageData,v as default};
